import base64
import hashlib
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding
from core.zalo.debugs import save
import json


def decrypt_zalo_v2_cipher(
    zcid: str,
    zcid_ext: str,
    cipher_b64: str,
    show_key: bool = False
) -> str:
    """
    Giải mã ciphertext AES-CBC của Zalo enc_ver=v2.

    Args:
        zcid: Giá trị zcid
        zcid_ext: Giá trị zcid_ext
        cipher_b64: Chuỗi ciphertext dạng Base64
        show_key: Có in encryptKey ra màn hình hay không

    Returns:
        Plaintext sau giải mã, thường là JSON string.
    """

    def split_even_odd(s: str):
        return list(s[::2]), list(s[1::2])

    # 1) Sinh encryptKey
    md5_hex = hashlib.md5(zcid_ext.encode("utf-8")).hexdigest().upper()

    md5_even, _ = split_even_odd(md5_hex)
    zcid_even, zcid_odd = split_even_odd(zcid)

    encrypt_key = (
        "".join(md5_even[:8])
        + "".join(zcid_even[:12])
        + "".join(list(reversed(zcid_odd))[:12])
    )

    if show_key:
        print("encryptKey =", encrypt_key)

    # 2) Base64 decode ciphertext
    ciphertext = base64.b64decode(cipher_b64)

    # 3) AES-CBC decrypt
    key = encrypt_key.encode("utf-8")
    iv = bytes(16)

    cipher = Cipher(
        algorithms.AES(key),
        modes.CBC(iv)
    )

    decryptor = cipher.decryptor()
    plaintext_padded = decryptor.update(ciphertext) + decryptor.finalize()

    # 4) PKCS7 unpad
    unpadder = padding.PKCS7(128).unpadder()
    plaintext = unpadder.update(plaintext_padded) + unpadder.finalize()

    return plaintext.decode("utf-8")

if __name__ == "__main__":
    zcid = "F6707B8C416DFF4BD449D7E5FAFEEB19548E0B4C1843AEE371F0ED1B26C1E0075DF6C388E4D1BA79A2055D80B35AE2503BC3AA593CFBF9DC5DAEB89987BCD7575799A38DDEF77D0A99D84EE635D3B41C8C16F4123CE9A11C139D943F66F57E56"

    zcid_ext = "38de56130dbe"

    cipher_b64 = """""".strip()

    try:
        result = decrypt_zalo_v2_cipher(
            zcid=zcid,
            zcid_ext=zcid_ext,
            cipher_b64=cipher_b64,
            show_key=True
        )

        # Lưu raw plaintext
        save("login_info_decrypted.txt", result, as_json=False)

        # Parse JSON rồi lưu đẹp
        decoded_data = json.loads(result)
        save("login_info_decrypted.json", decoded_data)

    except Exception as e:
        print("[ERROR] Giải mã thất bại:")
        print(e)